def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Find the row that is almost entirely one non-zero color, except possibly one cell
    # where a vertical non-zero line passes through.
    cross_r = cross_c = None

    # Detect intersection by locating a row with many same non-zero values
    for r in range(h):
        counts = {}
        for c in range(w):
            v = grid[r][c]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1

        if not counts:
            continue

        # Candidate horizontal color is the most frequent non-zero in the row
        horiz_color = max(counts, key=counts.get)
        horiz_count = counts[horiz_color]

        # A valid cross row has the horizontal color filling all but one cell,
        # or the whole row.
        if horiz_count >= w - 1:
            # Find the exceptional column, if any
            candidate_cols = []
            for c in range(w):
                if grid[r][c] != horiz_color:
                    if grid[r][c] != 0:
                        candidate_cols.append(c)
            if len(candidate_cols) == 1:
                cross_r, cross_c = r, candidate_cols[0]
                break

    # Fallback: detect by finding a column with many same non-zero values
    if cross_r is None:
        for c in range(w):
            counts = {}
            for r in range(h):
                v = grid[r][c]
                if v != 0:
                    counts[v] = counts.get(v, 0) + 1

            if not counts:
                continue

            vert_color = max(counts, key=counts.get)
            vert_count = counts[vert_color]

            if vert_count >= h - 1:
                candidate_rows = []
                for r in range(h):
                    if grid[r][c] != vert_color:
                        if grid[r][c] != 0:
                            candidate_rows.append(r)
                if len(candidate_rows) == 1:
                    cross_r, cross_c = candidate_rows[0], c
                    break

    # If no cross found, return grid unchanged
    if cross_r is None or cross_c is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    # Paint a 3x3 block of 4s centered at the intersection, preserving the center cell
    for rr in range(max(0, cross_r - 1), min(h, cross_r + 2)):
        for cc in range(max(0, cross_c - 1), min(w, cross_c + 2)):
            if rr == cross_r and cc == cross_c:
                continue
            out[rr][cc] = 4

    return out

